import json

# Build output with:
# - 2-pattern complete 3x2 filled LEFT +SHIFTED to center in V0,H0
# - V0,H1 gets right-shifted 3x2 of same 2-pattern
# - V1,H1 gets complete 3x2 of 2-pattern  
# - Similarly for 1-pattern and 4-pattern

output = [[0]*23 for _ in range(26)]

# Set barriers first
for r in [5, 11, 17, 23]:
    for c in range(23):
        output[r][c] = 8
for c in [5, 11, 17]:
    for r in range(26):
        output[r][c] = 8

def fill_3x2(section_r, section_c, color):
    """Fill 3x2 pattern at rows 2,3,4 cols 0,1 of section"""
    for dr in [2, 3, 4]:
        for dc in [0, 1]:
            output[section_r + dr][section_c + dc] = color

# Test input has incomplete patterns. Complete them:

# V0,H0: Complete left-side 3x2 with 2
fill_3x2(0, 0, 2)

# V0,H0 shifted LEFT to center: fill cols 1-2 at rows 2-4
for dr in [2, 3, 4]:
    for dc in [1, 2]:
        output[0 + dr][0 + dc] = 2

# V0,H1: right-shifted from V0,H0
for dr in [2, 3, 4]:
    for dc in [0, 1]:
        output[0 + dr][6 + dc] = 2

# V1,H0: center the 2 pattern
for dr in [2, 3, 4]:
    for dc in [1, 2]:
        output[6 + dr][0 + dc] = 2

# V1,H1: complete left 3x2 with 2
fill_3x2(6, 6, 2)

# V2: 4 patterns - complete and shift

# V2,H0: left 3x2 of 4
for dr in [2, 3, 4]:
    for dc in [0, 1]:
        output[12 + dr][0 + dc] = 4

# V2,H1: left 3x2 of 4
fill_3x2(12, 6, 4)

# V2,H2: 1 patterns left 3x2
for dr in [2, 3, 4]:
    for dc in [0, 1]:
        output[12 + dr][12 + dc] = 1

# V2,H3: left 3x2 of 1
fill_3x2(12, 18, 1)

# V3,H0: left 3x2 of 1 shifted
for dr in [2, 3, 4]:
    for dc in [0, 1]:
        output[18 + dr][0 + dc] = 1

# V3,H1: right-shifted 1s
for dr in [2, 3, 4]:
    for dc in [1, 2]:
        output[18 + dr][6 + dc] = 1

action = {"action": "submit", "grid": output}
print(json.dumps(action))

